package com.cryptostrategy.platform.leaderboard.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.evaluation.api.model.RankingVersion;import com.cryptostrategy.platform.experiment.api.ExperimentId;import java.util.List;import org.junit.jupiter.api.Test;
class LeaderboardFingerprintV1Test{@Test void canonicalOrderedContentAndRankingVersionAffectFingerprint(){var experiment=new ExperimentId("00000000000000000000000030");var evaluation=LeaderboardTestFixtures.evaluation("00000000000000000000000031",experiment,"0.8","a",true);var projector=new TopKProjector();var one=projector.project(experiment,new RankingVersion("ranking-v1"),1,10,List.of(evaluation));var two=projector.project(experiment,new RankingVersion("ranking-v2"),1,10,List.of(new com.cryptostrategy.platform.evaluation.api.model.EvaluationResult(evaluation.evaluationResultId(),evaluation.experimentId(),evaluation.backtestResultId(),evaluation.metricVersion(),new RankingVersion("ranking-v2"),evaluation.totalReturn(),evaluation.winRate(),evaluation.maximumDrawdown(),evaluation.numberOfTrades(),evaluation.overallScore(),evaluation.leaderboardEligible(),evaluation.fingerprint(),evaluation.evaluatedAt())));assertNotEquals(one.fingerprint(),two.fingerprint());}}
